package uz.mirix.tracelens.internal;
import org.springframework.beans.BeansException;import org.springframework.beans.factory.config.BeanPostProcessor;import org.springframework.web.client.RestTemplate;import uz.mirix.tracelens.TraceLensProperties;
public final class TraceLensRestTemplateBeanPostProcessor implements BeanPostProcessor {private final TraceLensProperties p;private final TraceLensClientHttpRequestInterceptor i;public TraceLensRestTemplateBeanPostProcessor(TraceLensProperties p,TraceLensClientHttpRequestInterceptor i){this.p=p;this.i=i;}public Object postProcessAfterInitialization(Object bean,String name)throws BeansException{if(!p.isEnabled()||!p.getHttpClient().isEnabled()||!(bean instanceof RestTemplate t))return bean;boolean present=t.getInterceptors().stream().anyMatch(x->x instanceof TraceLensClientHttpRequestInterceptor);if(!present)t.getInterceptors().add(i);return bean;}}
